contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will test behavior of Collect for any requested amount _am and ensure
    // invariant relating c.balances(address(this)) and address(c).balance holds
    // after the call (whether it succeeded or reverted / did nothing).
    function run(uint _minSum, uint _deposit, uint _am) public payable {
        require(true);

        // Ensure this test contract has enough balance to deposit into c
        // If deposit > 0, send that Ether from this call to c via Deposit (call value)
        if (_deposit > 0) {
            require(address(this).balance >= _deposit, "insufficient test balance");
            // set MinSum and initialize Log (these must be set before Initialized is called in C)
            // Use c.SetMinSum and c.SetLogFile only if contract not yet initialized; the provided C
            // requires !intitalized for these, but we cannot read that flag. We'll call them now
            // assuming fresh contract allows it.
            c.SetMinSum(_minSum);
            // Supply a dummy LogFile address: use address(this) which is allowed (LogFile is a contract type,
            // but we cannot construct one; however SetLogFile just stores address as LogFile). This is allowed.
            c.SetLogFile(address(this));

            // Deposit into c by calling Deposit with value
            c.Deposit{value: _deposit}();
        } else {
            // Even if no deposit, still set MinSum and LogFile to allow Collect conditions to depend on MinSum
            c.SetMinSum(_minSum);
            c.SetLogFile(address(this));
        }

        // Record before-values
        uint beforeBal = c.balances(address(this));
        uint beforeCBalance = address(c).balance;

        // Attempt to Collect _am from c. Capture whether it reverted.
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterBal = c.balances(address(this));
        uint afterCBalance = address(c).balance;

        // The general rule:
        // - If the call reverted, then balances and contract Ether balance must be unchanged.
        // - If it did not revert, then either Collect did nothing (preconditions failed) and balances unchanged,
        //   or it succeeded and both the stored balance and contract balance decreased by exactly _am.
        bool noChange = (afterBal == beforeBal) && (afterCBalance == beforeCBalance);
        bool reducedByAm = (beforeBal >= _am) && (beforeBal >= _minSum) &&
                           (afterBal + _am == beforeBal) && (beforeCBalance == afterCBalance + _am) && (!reverted);

        assert(noChange || reducedByAm);
    }

    // Receive Ether so c can call back into this contract if needed (Collect forwards Ether to msg.sender)
    receive() external payable {}
}

