contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller will deposit some amount and then attempt to collect some amount.
    // We check that if Collect does not revert then balances[msg.sender] decreased by _am
    // and the contract's balance decreased by at least _am.
    function run(uint depositAmt, uint _am) public payable {
        require(address(this).balance >= depositAmt);
        // ensure MinSum is low so that Collect can proceed based on balances
        // SetMinSum and SetLogFile must be callable before Initialized; call SetMinSum
        c.SetMinSum(1);

        // record contract balance before deposit
        uint beforeContractBal = address(c).balance;
        // record our recorded balance before deposit
        uint beforeRecorded = c.balances(address(this));

        // perform deposit into c
        c.Deposit{value: depositAmt}();

        // after deposit readings
        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // sanity: deposit must have increased recorded balance by depositAmt
        // (this is an observed property used for the main assertion later)
        // Call Collect and capture whether it reverted
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // final readings
        uint finalRecorded = c.balances(address(this));
        uint finalContractBal = address(c).balance;

        // General property: if Collect did not revert, then finalRecorded == afterRecorded - _am
        // and finalContractBal <= afterContractBal - _am (contract balance decreased by at least _am)
        // Also require that afterRecorded >= _am (otherwise Collect should have reverted) OR reverted==true
        assert(reverted || (afterRecorded >= _am && finalRecorded + _am == afterRecorded && afterContractBal >= finalContractBal + _am));
    }

    // allow receiving refunds when Collect triggers external call back
    receive() external payable {}
}

