contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to set MinSum, an initial deposit amount, and a collect amount.
    // The test will: set MinSum, deposit some Ether, then attempt Collect(_am).
    // It then asserts the general rule relating revert flag, balances, MinSum, and contract balance.
    function run(uint _minSum, uint depositAmt, uint _am) public payable {
        // ensure the test contract has enough balance to send depositAmt
        require(address(this).balance >= depositAmt);

        // Only allowed to set MinSum before c is initialized; this mirrors intended usage.
        c.SetMinSum(_minSum);

        // Record storage-observable values before actions
        uint beforeUserBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;
        uint beforeMin = c.MinSum();

        // Make a deposit to c of depositAmt
        c.Deposit{value: depositAmt}();

        // Record after-deposit values
        uint afterUserBal = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // Now attempt Collect(_am) and capture whether it reverted
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after Collect attempt
        uint finalUserBal = c.balances(address(this));
        uint finalContractBal = address(c).balance;
        uint currentMin = c.MinSum();

        // GENERAL RULE asserted for ALL inputs:
        // - The MinSum observed by calls is stable (SetMinSum was called earlier so MinSum == beforeMin == currentMin)
        // - If Collect did NOT revert, then before the Collect call the user's recorded balance must have been >= MinSum and >= _am,
        //   and after Collect the user's recorded balance must be <= balance before Collect (i.e. not increased),
        //   and the contract's Ether balance must have decreased by exactly _am.
        // - If Collect reverted, then either the precondition failed (balance < MinSum or balance < _am) or the transfer failed;
        //   we assert that if it reverted then at least one of (precondition fail) holds (we don't assume transfer behavior on revert).

        assert(
            // MinSum unchanged
            currentMin == beforeMin
            // AND either Collect succeeded and the strong effects hold
            && (
                (!reverted)
                ? (
                    // preconditions must have been satisfied before Collect: user's balance at afterDeposit time (which is before Collect)
                    (afterUserBal >= beforeMin && afterUserBal >= _am)
                    // user's recorded balance after Collect is not greater than before Collect
                    && (finalUserBal <= afterUserBal)
                    // contract balance decreased by exactly _am
                    && (afterContractBal == finalContractBal + _am)
                  )
                // OR Collect reverted, in which case at least one precondition was false at time of call
                : (
                    (afterUserBal < beforeMin) || (afterUserBal < _am)
                  )
            )
        );
    }

    // Allow the test contract to receive Ether so it can forward deposits
    receive() external payable {}
}

