contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint setMin, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "need deposit funds");
        // Initialize MinSum and LogFile once before making deposits/collects
        // SetMinSum and SetLogFile require intitalized == false; we won't call Initialized here.
        c.SetMinSum(setMin);

        // Make a deposit to the contract on behalf of this test contract (msg.sender for c calls is this contract)
        c.Deposit{value: depositAmount}();

        // Read stored balance before Collect and contract balance
        uint balBefore = c.balances(address(this));
        uint contractEthBefore = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractEthAfter = address(c).balance;

        // General rule:
        // - If stored balance before is < MinSum then Collect must revert (so reverted == true).
        // - Else if stored balance before >= MinSum and >= collectAmount then Collect must not revert
        //   and balances and contract ETH decrease by collectAmount.
        // - Else (stored >= MinSum but < collectAmount) Collect reverts.
        uint minSum = c.MinSum();

        // Formulate as single assert combining the cases
        assert(
            // case 1: below MinSum => must revert and nothing changed
            ((balBefore < minSum) && reverted)
            ||
            // case 2: enough >= MinSum and enough for amount => must not revert and decreases by collectAmount
            ((balBefore >= minSum && balBefore >= collectAmount) && !reverted
                && balAfter + collectAmount == balBefore
                && contractEthAfter + collectAmount == contractEthBefore)
            ||
            // case 3: balance >= MinSum but insufficient for requested amount => must revert
            ((balBefore >= minSum && balBefore < collectAmount) && reverted)
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

